// Sketch of a WDK driver registering a process notify routine (not a full driver).
#include <ntddk.h>

void OnProcess(PEPROCESS Process, HANDLE ProcessId, PPS_CREATE_NOTIFY_INFO CreateInfo)
{
    if (CreateInfo == NULL) {
        return;                      // NULL means the process is exiting
    }
    // CreateInfo->ImageFileName, CreateInfo->CommandLine, CreateInfo->ParentProcessId
    // are queued for the user-mode service here.
    // To block the launch, a driver sets an error code:
    // CreateInfo->CreationStatus = STATUS_ACCESS_DENIED;
}

// In DriverEntry:   PsSetCreateProcessNotifyRoutineEx(OnProcess, FALSE);
// When unloading:   PsSetCreateProcessNotifyRoutineEx(OnProcess, TRUE);

# Simplified model of Sysmon's documented filter logic for one event type:
# same field = OR, different fields = AND, exclude beats include.
def field_match(rules, event):
    by_field = {}
    for field, cond, value in rules:
        by_field.setdefault(field, []).append((cond, value))
    def ok(cond, value, actual):
        a, v = actual.lower(), value.lower()
        return {"is": a == v, "end with": a.endswith(v), "contains": v in a}[cond]
    return all(any(ok(c, v, event[f]) for c, v in conds) for f, conds in by_field.items())

include = [("DestinationPort", "is", "443"), ("DestinationPort", "is", "80")]
exclude = [("Image", "end with", "iexplore.exe")]

def logged(event):
    if exclude and field_match(exclude, event):
        return False            # exclude wins
    return field_match(include, event)

events = [
    {"Image": r"C:\Tools\updater.exe", "DestinationPort": "443"},
    {"Image": r"C:\Program Files\Internet Explorer\iexplore.exe", "DestinationPort": "443"},
    {"Image": r"C:\Tools\updater.exe", "DestinationPort": "8080"},
]
for e in events:
    print(e["Image"].split("\\")[-1], e["DestinationPort"], ":", "logged" if logged(e) else "dropped")

# Output:
# updater.exe 443 : logged
# iexplore.exe 443 : dropped
# updater.exe 8080 : dropped

